import { createAgentDeviceClient } from 'agent-device';
import { leaseSession } from './session.js';
process.once('message', (request) => {
    void allocate(request).then((grant) => process.send?.({ grant }, () => process.disconnect?.()), (cause) => process.send?.({ error: cause instanceof Error ? cause.message : String(cause) }, () => process.disconnect?.()));
});
async function allocate({ stateDir, allocate: options }) {
    const lease = await createAgentDeviceClient({ stateDir, session: leaseSession(stateDir) }).leases.allocate(options);
    return { leaseId: lease.leaseId, tenantId: lease.tenantId, runId: lease.runId, retainOnClose: lease.retainOnClose === true };
}
